-full flex items-center justify-between gap-3 px-4 py-3 border transition-colors bg-seyitler-bg4 border-seyitler-bg4 text-seyitler-txt hover:bg-gray-50" href="<?= url('/about-us/mission-vision') ?>"><span class="text-left">Misyon ve Vizyon</span><svg class="lucide lucide-chevron-right-icon size-4" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="w-full flex items-center justify-between gap-3 px-4 py-3 border transition-colors bg-seyitler-bg4 border-seyitler-bg4 text-seyitler-txt hover:bg-gray-50" href="<?= url('/about-us/values') ?>"><span class="text-left">Değerler</span><svg class="lucide lucide-chevron-right-icon size-4" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a aria-current="page" class="router-link-active router-link-exact-active w-full flex items-center justify-between gap-3 px-4 py-3 border transition-colors bg-seyitler-bg3 border-seyitler-bg3 text-white" href="<?= url('/about-us/organization') ?>"><span class="text-left">Organizasyon Yapısı</span><svg class="lucide lucide-chevron-right-icon size-4" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="w-full flex items-center justify-between gap-3 px-4 py-3 border transition-colors bg-seyitler-bg4 border-seyitler-bg4 text-seyitler-txt hover:bg-gray-50" href="<?= url('/about-us/sustainability') ?>"><span class="text-left">Sürdürülebilirlik</span><svg class="lucide lucide-chevron-right-icon size-4" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="w-full flex items-center justify-between gap-3 px-4 py-3 border transition-colors bg-seyitler-bg4 border-seyitler-bg4 text-seyitler-txt hover:bg-gray-50" href="<?= url('/about-us/human-resources') ?>"><span class="text-left">İnsan Kaynakları</span><svg class="lucide lucide-chevron-right-icon size-4" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="m9 18 6-6-6-6"></path></svg></a></li></ul></aside><div class="md:col-span-8 lg:col-span-9 min-h-64"><div class="prose max-w-none"><div class="px-5 mx-auto xl:px-0 max-w-7xl"><div class="w-full border-b border-gray-200"><div class="flex gap-6"><button class="text-seyitler-primary border-seyitler-primary font-semibold -mb-px pb-2.5 px-1 text-base md:text-lg border-b-4 border-transparent transition-colors" type="button">Başkanın Mesajı</button><button class="text-gray-700 hover:text-gray-900 -mb-px pb-2.5 px-1 text-base md:text-lg border-b-4 border-transparent transition-colors" type="button">Yönetim Şeması</button></div></div><div class="pt-8"><div class="grid grid-cols-1 gap-6 lg:grid-cols-3"><div class="lg:col-span-1"><div class="aspect-[4/5] rounded-md"><img alt="" src="<?= asset('assets/images/mehmet_faysal_gokalp.jpeg') ?>"/></div></div><div class="lg:col-span-2"><h2 class="text-2xl md:text-3xl font-semibold mb-3">Başkanın Mesajı (Chairman / General Manager’s Message)</h2><h3 class="text-xl md:text-2xl font-medium relative mb-4 pb-2 after:absolute after:left-0 after:bottom-0 after:h-[3px] after:w-16 after:bg-seyitler-primary">Bilimle Üretmek, Güvenle Büyümek</h3><div class="prose prose-seyitler max-w-none text-seyitler-txt"><p>Değerli İş Ortaklarımız,</p><p>Seyitler Kimya olarak, Türkiye’nin medikal cihaz üretim gücünü bilimsel inovasyonla buluşturduğumuz 30 yılı aşkın bir yolculuğun gururunu yaşıyoruz.</p><p>Manisa Turgutlu’daki tesislerimizde geliştirdiğimiz ürünler, yalnızca ulusal pazarda değil, dünya çapında sağlık profesyonellerinin güvenini kazanmıştır.</p><p>Her projemizde “bilimden ürüne, üründen sağlığa” yaklaşımını benimsiyor; üretim teknolojilerimizi sürekli geliştirerek ülkemizin katma değerli üretim hedeflerine katkı sağlıyoruz.</p><p>Ar-Ge merkezimiz, TÜBİTAK ve TÜSEB destekli projeleriyle yeni nesil tıbbi yapışkan teknolojileri geliştirirken; ihracat ağımız, yerli üretimi global sahneye taşımaktadır.</p><p>Geleceğe dair vizyonumuz nettir: inovasyon, sürdürülebilirlik ve insan odaklı üretim ilkeleriyle her geçen gün daha güçlü bir Seyitler Kimya inşa etmek.</p><p>Üretime emek veren tüm ekip arkadaşlarımıza, iş ortaklarımıza ve bizi tercih eden sağlık profesyonellerine içten teşekkürlerimi sunarım.</p><p>Saygılarımla,</p><p>Prof.Dr. Mehmet Faysal GÖKALP</p><p>Yönetim Kurulu Başkanı / Genel Müdür</p><p>Seyitler Kimya A.Ş.</p></div></div></div></div></div></div></div></div></div></section></div><script>
        document.addEventListener("DOMContentLoaded", function() {
            var btnMsg = document.getElementById("tab-btn-message") || document.querySelector("[data-tab='message']");
            var btnChart = document.getElementById("tab-btn-chart") || document.querySelector("[data-tab='chart']");
            var paneMsg = document.getElementById("tab-pane-message");
            var paneChart = document.getElementById("tab-pane-chart");

            if (btnMsg && btnChart) {
                btnMsg.addEventListener("click", function() {
                    btnMsg.className = "px-6 py-3 text-sm font-semibold transition-colors relative text-seyitler-primary after:absolute after:bottom-0 after:left-0 after:right-0 after:h-0.5 after:bg-seyitler-primary cursor-pointer";
                    btnChart.className = "px-6 py-3 text-sm font-semibold transition-colors relative text-gray-500 hover:text-gray-700 cursor-pointer";
                    if (paneMsg) paneMsg.classList.remove("hidden");
                    if (paneChart) paneChart.classList.add("hidden");
                });
                btnChart.addEventListener("click", function() {
                    btnChart.className = "px-6 py-3 text-sm font-semibold transition-colors relative text-seyitler-primary after:absolute after:bottom-0 after:left-0 after:right-0 after:h-0.5 after:bg-seyitler-primary cursor-pointer";
                    btnMsg.className = "px-6 py-3 text-sm font-semibold transition-colors relative text-gray-500 hover:text-gray-700 cursor-pointer";
                    if (paneChart) paneChart.classList.remove("hidden");
                    if (paneMsg) paneMsg.classList.add("hidden");
                });
            }
        });
        </script>